     1	import { onlineManager } from '@tanstack/react-query';
     2	import { act, screen, waitFor, within } from '@testing-library/react';
     3	import userEvent from '@testing-library/user-event';
     4	import { describe, expect, it } from 'vitest';
     5	import { HarnessReadinessStateSchema } from '@graphgoblin/contracts';
     6	import { readinessMessage } from '@graphgoblin/domain';
     7	import { FakeApi, problem } from '../../__fixtures__/fake-api.js';
     8	import { renderWith } from '../../__fixtures__/render.js';
     9	import { keys } from '../../api/queries.js';
    10	import { PreflightSection } from './PreflightSection.js';
    11	
    12	const LABELS = {
    13	  ready: 'Ready',
    14	  unknown: 'Unknown',
    15	  'cli-missing': 'CLI not found',
    16	  'cli-incompatible': 'CLI update needed',
    17	  auth: 'Sign-in needed',
    18	  quota: 'Usage limit',
    19	  transport: 'Connection failed',
    20	} as const;
    21	const TONES = {
    22	  ready: 'good',
    23	  unknown: 'warn',
    24	  'cli-missing': 'bad',
    25	  'cli-incompatible': 'bad',
    26	  auth: 'bad',
    27	  quota: 'warn',
    28	  transport: 'warn',
    29	} as const;
    30	
    31	function claude(state: keyof typeof LABELS): FakeApi['preflight'][number] {
    32	  return {
    33	    harness: 'claude',
    34	    state,
    35	    ok: state === 'ready',
    36	    authenticated: state === 'ready',
    37	    ...(state === 'ready' ? { authMethod: 'claude.ai' as const } : {}),
    38	    problems: state === 'ready' ? [] : [readinessMessage('claude', state)],
    39	    models: [{ model: 'claude-opus-5-5', efforts: ['high'] }],
    40	  };
    41	}
    42	
    43	const region = () => screen.getByRole('region', { name: 'Harness preflight' });
    44	const retry = () => within(region()).getByRole('button', { name: 'Retry preflight' });
    45	const badge = (harness: string) =>
    46	  within(region())
    47	    .getAllByRole('listitem')
    48	    .find((item) => within(item).queryByText(harness, { selector: 'code' }))
    49	    ?.querySelector('[data-state]');
    50	
    51	describe('readiness state display', () => {
    52	  it.each(HarnessReadinessStateSchema.options)(
    53	    'labels %s on its badge without implying model access',
    54	    async (state) => {
    55	      const api = new FakeApi();
    56	      api.preflight = [claude(state)];
    57	      renderWith(<PreflightSection />, '/', api);
    58	      const label = await within(region()).findByText(LABELS[state]);
    59	      const shown = label.closest('[data-state]');
    60	      expect(shown).toHaveAttribute('data-state', state);
    61	      expect(shown).toHaveClass(`bg-status-${TONES[state]}-bg`);
    62	      // The enum value itself is never the visible text.
    63	      expect(within(region()).queryByText(state)).toBeNull();
    64	      const listed = screen.getByText('listed by adapter');
    65	      expect(listed.closest('.rounded-full')).toHaveClass('bg-status-neutral-bg');
    66	      expect(screen.getByText(/do not confirm account access/)).toBeInTheDocument();
    67	      expect(screen.queryByText(/supported by adapter|model unavailable/)).toBeNull();
    68	      if (state === 'ready') expect(screen.getByText('Signed in with Claude.ai.')).toBeVisible();
    69	      else
    70	        expect(screen.getByText(readinessMessage('claude', state)).closest('ul')).toHaveClass(
    71	          TONES[state] === 'bad' ? 'text-status-bad-fg' : 'text-status-warn-fg',
    72	        );
    73	    },
    74	  );
    75	
    76	  it('keeps the last result while rechecking, then shows the error view and recovers on retry', async () => {
    77	    const api = new FakeApi();
    78	    api.preflight = [
    79	      {
    80	        harness: 'codex',
    81	        state: 'ready',
    82	        ok: true,
    83	        version: '0.160.0',
    84	        authenticated: true,
    85	        problems: [],
    86	      },
    87	      claude('auth'),
    88	    ];
    89	    const { queryClient } = renderWith(<PreflightSection />, '/', api);
    90	    expect(await within(region()).findByText('Sign-in needed')).toBeVisible();
    91	    expect(within(region()).getByText('v0.160.0')).toBeVisible();
    92	    expect(retry()).toBeEnabled();
    93	    const status = within(region()).getByRole('status');
    94	    expect(status).toHaveTextContent('');
    95	
    96	    let finish!: (response: Response) => void;
    97	    api.override(
    98	      'GET /harness/preflight',
    99	      () =>
   100	        new Promise<Response>((resolve) => {
   101	          finish = resolve;
   102	        }),
   103	    );
   104	    let refresh!: Promise<void>;
   105	    act(() => {
   106	      // A window-focus refetch is an ordinary background refetch of the same query.
   107	      refresh = queryClient.refetchQueries({ queryKey: keys.preflight });
   108	    });
   109	    await waitFor(() => expect(status).toHaveTextContent('Rechecking…'));
   110	    expect(status).toHaveClass('text-muted');
   111	    expect(retry()).toBeDisabled();
   112	    // Badges do not flip to checking during a recheck.
   113	    expect(badge('codex')).toHaveAttribute('data-state', 'ready');
   114	    expect(badge('claude')).toHaveAttribute('data-state', 'auth');
   115	    expect(within(region()).queryByText('Checking…')).toBeNull();
   116	    // The removed duplicate paragraphs never appear.
   117	    expect(screen.queryByText(/Checking harness readiness|Harness readiness unknown/)).toBeNull();
   118	
   119	    await act(async () => {
   120	      finish(problem(503, 'FAILED', 'Temporary failure'));
   121	      await refresh;
   122	    });
   123	    // A failed request replaces the list with one error view; no stale badge remains.
   124	    expect(await within(region()).findByText('Could not load preflight')).toBeVisible();
   125	    expect(within(region()).getByText('Temporary failure (FAILED)')).toBeVisible();
   126	    expect(within(region()).queryByText('Ready')).toBeNull();
   127	    expect(within(region()).queryByText('Sign-in needed')).toBeNull();
   128	    expect(status).toHaveTextContent('');
   129	    expect(retry()).toBeEnabled();
   130	
   131	    api.override('GET /harness/preflight', () =>
   132	      Promise.resolve(Response.json({ items: [claude('ready')] })),
   133	    );
   134	    const before = api.calls.filter((call) => call.path === '/harness/preflight').length;
   135	    await userEvent.setup().click(retry());
   136	    expect(await within(region()).findByText('Ready')).toBeVisible();
   137	    expect(api.calls.filter((call) => call.path === '/harness/preflight')).toHaveLength(before + 1);
   138	    expect(within(region()).queryByText('Could not load preflight')).toBeNull();
   139	  });
   140	
   141	  it('shows the loading text alone and disables Retry during the first check', async () => {
   142	    const api = new FakeApi();
   143	    api.override('GET /harness/preflight', () => new Promise<Response>(() => undefined));
   144	    renderWith(<PreflightSection />, '/', api);
   145	    expect(await within(region()).findByText('Loading preflight…')).toBeVisible();
   146	    expect(retry()).toBeDisabled();
   147	    expect(within(region()).getByRole('status')).toHaveTextContent('');
   148	    expect(within(region()).queryByText('Checking…')).toBeNull();
   149	  });
   150	
   151	  it('keeps the last result while offline and says so', async () => {
   152	    const api = new FakeApi();
   153	    const { queryClient } = renderWith(<PreflightSection />, '/', api);
   154	    expect(await within(region()).findByText('Ready')).toBeVisible();
   155	    try {
   156	      act(() => {
   157	        window.dispatchEvent(new Event('offline'));
   158	      });
   159	      act(() => {
   160	        void queryClient.refetchQueries({ queryKey: keys.preflight });
   161	      });
   162	      expect(await within(region()).findByText('Offline; showing the last check.')).toBeVisible();
   163	      expect(badge('codex')).toHaveAttribute('data-state', 'ready');
   164	      expect(retry()).toBeEnabled();
   165	    } finally {
   166	      onlineManager.setOnline(true);
   167	    }
   168	  });
   169	});

