    ...(state === 'ready' ? { authMethod: 'claude.ai' as const } : {}),
    problems: state === 'ready' ? [] : [readinessMessage('claude', state)],
    models: [{ model: 'claude-opus-5-5', efforts: ['high'] }],
  };
