import { act, fireEvent, screen, waitFor, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, expect, it, vi } from 'vitest';
import { defaultScheduler, notifyManager } from '@tanstack/react-query';
import { CODEX_PLUGIN_OBSERVABILITY_NOTICE } from '@graphgoblin/domain';
import { FakeApi, problem, TS } from '../__fixtures__/fake-api.js';
import { renderApp } from '../__fixtures__/render.js';
import { useApiKeyStore } from '../api/api-key.js';

function seeded(source: 'harness' | 'litellm' = 'harness'): FakeApi {
  const api = new FakeApi();
  api.catalog = [
    {
      harness: 'codex',
      source,
      model: 'gpt-6-luna',
      displayName: 'Luna',
      efforts: ['low', 'high'],
      defaultEffort: 'low',
      enabled: true,
    },
    {
      harness: 'codex',
      source,
      model: 'gpt-6-sol',
      displayName: 'Sol',
      efforts: ['medium'],
      defaultEffort: 'medium',
      enabled: false,
    },
  ];
  api.secretList = [{ name: 'jev-api-key', createdAt: TS, updatedAt: TS }];
  api.apiKeyList = [
    { id: 'k1', ownerId: 'local', label: 'mcp', scopes: ['*'], createdAt: TS, current: false },
    {
      id: 'k2',
      ownerId: 'local',
      label: 'old',
      scopes: ['runs:write'],
      createdAt: TS,
      revokedAt: TS,
      current: false,
    },
  ];
  api.preflight = [
    {
      harness: 'codex',
      state: 'ready',
      ok: true,
      version: '1.2',
      authenticated: true,
      problems: [],
    },
    {
      harness: 'other',
      state: 'unknown',
      ok: false,
      version: '',
      authenticated: false,
      problems: ['not logged in'],
    },
  ];
  return api;
}

describe('SettingsPage', () => {
  it.each([
    ['Delete gpt-6-luna', 'Confirm delete gpt-6-luna', 'Model catalog'],
    ['Delete secret jev-api-key', 'Confirm delete jev-api-key', 'Secrets'],
    ['Revoke mcp', 'Confirm revoke mcp', 'API keys'],
  ] as const)(
    'recovers heading focus when %s refreshes before React commits its row removal',
    async (label, confirmation, heading) => {
      const api = seeded('litellm');
      const { queryClient } = renderApp('/settings', api);
      const trigger = await screen.findByRole('button', { name: label });
      await waitFor(() => expect(queryClient.isFetching()).toBe(0));
      await userEvent.setup().click(trigger);
      // The removal watch expires 500 ms after refresh settles. Hold its clock as well as
      // rendering: real-time user-event/waitFor delays can otherwise expire it under load.
      vi.useFakeTimers({ toFake: ['setTimeout', 'clearTimeout'] });
      const notifications: (() => void)[] = [];
      const frames: FrameRequestCallback[] = [];
      const frame = vi.spyOn(globalThis, 'requestAnimationFrame').mockImplementation((callback) => {
        frames.push(callback);
        return frames.length;
      });
      notifyManager.setScheduler((callback) => notifications.push(callback));
      try {
        // Drain promise continuations and zero-delay tasks (including dialog close) without
        // advancing to the watch's expiry. act commits the close before notification release.
        await act(async () => {
          fireEvent.click(screen.getByRole('button', { name: confirmation }));
          await vi.advanceTimersByTimeAsync(0);
        });
        expect(queryClient.isFetching()).toBe(0);
        expect(screen.queryByRole('alertdialog')).not.toBeInTheDocument();
        act(() => frames.splice(0).forEach((callback) => callback(0)));
        // The request settled and the old frame ran; the query's render notification is held.
        expect(trigger).toHaveFocus();
        expect(trigger).toBeInTheDocument();
        expect(notifications.length).toBeGreaterThan(0);
        await act(() => Promise.resolve(notifications.splice(0).forEach((callback) => callback())));
        expect(trigger).not.toBeInTheDocument();
        expect(screen.getByRole('heading', { name: heading })).toHaveFocus();
      } finally {
        notifyManager.setScheduler(defaultScheduler);
        try {
          await act(() =>
            Promise.resolve(notifications.splice(0).forEach((callback) => callback())),
          );
        } finally {
          frame.mockRestore();
          vi.useRealTimers();
        }
      }
    },
  );

