      ).toEqual([]);
      await userEvent.setup().selectOptions(effort, 'high');
      await waitFor(() =>
        expect(api.settingsValues).toEqual({
          defaults: {
            byHarness: {
              codex: { model: 'gpt-6-luna', effort: 'low' },
              claude: { effort: 'high' },
            },
          },
        }),
      );
      expect(model).toHaveValue('');
    },
  );

  it('keeps Claude defaults per harness and enables Fable through the catalog', async () => {
    const user = userEvent.setup();
    const api = seeded();
    api.catalog.push(
      {
        harness: 'claude',
        source: 'harness',
        model: 'claude-opus-5-5',
        displayName: 'Claude Opus 5.5',
        efforts: ['low', 'medium', 'high', 'xhigh', 'max'],
        defaultEffort: 'high',
        enabled: true,
      },
      {
        harness: 'claude',
        source: 'harness',
        model: 'claude-fable-5-1',
        displayName: 'Fable 5.1',
        efforts: ['low', 'medium', 'high', 'xhigh', 'max'],
        defaultEffort: 'high',
        enabled: false,
      },
    );
    api.preflight = [
      { harness: 'codex', state: 'ready', ok: true, authenticated: true, problems: [] },
      {
        harness: 'claude',
        state: 'ready',
        ok: true,
        version: '2.1.285',
        authenticated: true,
        authMethod: 'claude.ai',
        problems: [],
        supportedPolicies: [],
        models: [
          {
            model: 'claude-opus-5-5',
            efforts: ['low', 'medium', 'high', 'xhigh', 'max'],
          },
          {
            model: 'claude-fable-5-1',
