    await user.click(confirm);
    expect(confirm).toHaveTextContent('Deleting…');
    expect(confirm).toBeDisabled();
    expect(screen.getByRole('button', { name: 'Keep' })).toBeDisabled();
    fireEvent.click(confirm);
    expect(api.callsTo('DELETE', '/secrets/jev-api-key')).toHaveLength(1);
    await act(() => Promise.resolve(finish()));
    await waitFor(() => expect(screen.queryByRole('alertdialog')).not.toBeInTheDocument());
    await waitFor(() => expect(screen.getByRole('heading', { name: 'Secrets' })).toHaveFocus());
  });

  it('warns about browser access only when revoking the current key', async () => {
    useApiKeyStore.getState().save('gg_browser_key');
    const api = seeded();
    api.apiKeyList[0]!.current = true;
    renderApp('/settings', api);
    const user = userEvent.setup();
    await user.click(await screen.findByRole('button', { name: 'Revoke mcp' }));
    expect(screen.getByText('This browser')).toBeInTheDocument();
    expect(screen.getByRole('alertdialog')).toHaveTextContent(
      'Revoking this key will sign this browser out and show the API key panel. Enter another valid key to continue.',
    );
    await user.click(screen.getByRole('button', { name: 'Keep' }));
  });
});

describe('Claude catalog enablement and readiness', () => {
  it.each([true, false])(
    'keeps owner enable switches usable with failed readiness and login %s',
    async (authenticated) => {
      const api = seeded();
      api.catalog.push({
        harness: 'claude',
        source: 'harness',
        model: 'claude-fable-5-1',
        displayName: 'Fable 5.1',
        efforts: ['high'],
        defaultEffort: 'high',
        enabled: true,
      });
      api.preflight.push({
        harness: 'claude',
        state: 'cli-incompatible',
        ok: false,
        version: '2.1.287',
        authenticated,
        authMethod: authenticated ? 'claude.ai' : null,
        problems: [
          'Claude CLI 2.1.287 does not list required options: --restricted. Update the Claude CLI, then retry preflight.',
        ],
        models: [{ model: 'claude-fable-5-1', efforts: ['high'] }],
      });
      renderApp('/settings', api);
      expect(
        await screen.findByText('Enabled in catalog. Claude readiness: CLI update needed.'),
      ).toBeInTheDocument();
      const toggle = await screen.findByRole('switch', { name: 'Enable Fable 5.1' });
      expect(toggle).toBeChecked();
      expect(toggle).not.toHaveAttribute('aria-disabled', 'true');
      if (authenticated) expect(screen.getByText('Signed in with Claude.ai.')).toBeInTheDocument();
      else expect(screen.queryByText('Signed in with Claude.ai.')).not.toBeInTheDocument();
      await userEvent.setup().click(toggle);
      await waitFor(() => expect(toggle).not.toBeChecked());
      expect(
        screen.getByText('Disabled in catalog. Claude readiness: CLI update needed.'),
      ).toBeInTheDocument();
    },
  );
});

describe('Codex catalog rows and readiness', () => {
  it('notes a known Codex failure on Codex rows as for Claude, but not during the first check', async () => {
    const pending = seeded();
    pending.override('GET /harness/preflight', () => new Promise<Response>(() => undefined));
    const first = renderApp('/settings', pending);
    expect(await screen.findByRole('switch', { name: 'Enable Luna' })).toBeInTheDocument();
    expect(screen.queryByText(/readiness:/)).not.toBeInTheDocument();
    first.unmount();

    const api = seeded();
    api.preflight = [
      {
        harness: 'codex',
        state: 'transport',
        ok: false,
        problems: [
          "Codex reported a connection or provider service error. Check the network connection and the provider's service status, then retry preflight.",
        ],
      },
    ];
    renderApp('/settings', api);
    const catalog = await screen.findByRole('region', { name: 'Model catalog' });
    expect(
      await within(catalog).findByText('Enabled in catalog. Codex readiness: Connection failed.'),
    ).toBeInTheDocument();
    expect(
      within(catalog).getByText('Disabled in catalog. Codex readiness: Connection failed.'),
    ).toBeInTheDocument();
  });

  it('keeps a Codex sign-in failure visible everywhere, with the plugin notice only in preflight', async () => {
    const api = seeded();
    const signIn = 'Codex sign-in is missing or invalid. Run codex login, then retry preflight.';
    api.preflight = [
      { harness: 'codex', state: 'auth', ok: false, authenticated: false, problems: [signIn] },
    ];
    renderApp('/settings', api);
    const preflight = await screen.findByRole('region', { name: 'Harness preflight' });
    const problemLine = await within(preflight).findByText(signIn);
    const codexRow = problemLine.closest('ul')!.closest('li')!;
    expect(within(codexRow).getByText('Sign-in needed')).toBeVisible();
    expect(problemLine.closest('ul')).toHaveClass('text-status-bad-fg');
    const [notice, ...extra] = codexNotices(document.body);
    expect(extra).toHaveLength(0);
    expect(codexRow).toContainElement(notice!);
    expect(problemLine.closest('ul')).not.toContainElement(notice!);
    // The short readiness lines elsewhere are unchanged and do not repeat the notice.
    const catalog = screen.getByRole('region', { name: 'Model catalog' });
    expect(
      await within(catalog).findByText('Enabled in catalog. Codex readiness: Sign-in needed.'),
    ).toBeInTheDocument();
    expect(
      within(screen.getByRole('region', { name: 'Defaults' })).getByText(
        'Codex readiness: Sign-in needed. See Harness preflight below.',
      ),
    ).toBeInTheDocument();
    expect(codexNotices(catalog)).toHaveLength(0);
    expect(codexNotices(screen.getByRole('region', { name: 'Defaults' }))).toHaveLength(0);
  });
});

